import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const width = 7.0;
  const height = 0.35;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create canvases for textures
  const canvas = document.createElement('canvas');
  canvas.width = 2048;
  canvas.height = 256;
  const c = canvas.getContext('2d');

  const emissiveCanvas = document.createElement('canvas');
  emissiveCanvas.width = 2048;
  emissiveCanvas.height = 256;
  const eCtx = emissiveCanvas.getContext('2d');

  const colors = {
    surface: '#111117',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#23232b'
  };

  // Scaling
  const pixelsPerUnitX = canvas.width / width;
  const pixelsPerUnitY = canvas.height / height;
  const tickWidthPx = Math.round(0.14 * pixelsPerUnitX);
  const tickHeightPx = Math.round(0.14 * pixelsPerUnitY);
  const hairlinePx = 1;

  // Albedo texture
  c.fillStyle = colors.surface;
  c.fillRect(0, 0, canvas.width, canvas.height);

  // Emissive texture
  eCtx.fillStyle = '#000000';
  eCtx.fillRect(0, 0, emissiveCanvas.width, emissiveCanvas.height);

  // Hairlines
  c.strokeStyle = colors.hairline;
  c.lineWidth = hairlinePx;
  c.beginPath();
  c.moveTo(0, 4);
  c.lineTo(canvas.width, 4);
  c.stroke();
  c.beginPath();
  c.moveTo(0, canvas.height - 4);
  c.lineTo(canvas.width, canvas.height - 4);
  c.stroke();

  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  c.font = '700 26px "JetBrains Mono"';
  c.fillStyle = colors.paper;
  c.textBaseline = 'middle';

  const midY = canvas.height / 2;
  const gapPx = Math.round(0.5 * pixelsPerUnitX);
  let pos = 60;
  const entrySpacingPx = 280;

  // Draw content twice for seamless loop
  for (let cycle = 0; cycle < 2; cycle++) {
    for (const entry of entries) {
      // Tick marks
      const tickX = pos;
      const tickY = midY - tickHeightPx / 2;

      c.fillStyle = colors.accent;
      c.fillRect(tickX, tickY, tickWidthPx, tickHeightPx);

      eCtx.fillStyle = '#ffffff';
      eCtx.fillRect(tickX, tickY, tickWidthPx, tickHeightPx);

      pos += tickWidthPx + gapPx;

      // Text
      c.fillStyle = colors.paper;
      c.fillText(entry, pos, midY);

      pos += entrySpacingPx + gapPx;
    }
  }

  // Edge fade gradient
  const fadeGrad = c.createLinearGradient(0, 0, canvas.width, 0);
  fadeGrad.addColorStop(0, 'rgba(11,11,16,1)');
  fadeGrad.addColorStop(0.09, 'rgba(11,11,16,0)');
  fadeGrad.addColorStop(0.91, 'rgba(11,11,16,0)');
  fadeGrad.addColorStop(1, 'rgba(11,11,16,1)');

  c.globalCompositeOperation = 'destination-in';
  c.fillStyle = fadeGrad;
  c.fillRect(0, 0, canvas.width, canvas.height);
  c.globalCompositeOperation = 'source-over';

  eCtx.globalCompositeOperation = 'destination-in';
  eCtx.fillStyle = fadeGrad;
  eCtx.fillRect(0, 0, emissiveCanvas.width, emissiveCanvas.height);
  eCtx.globalCompositeOperation = 'source-over';

  // Textures
  const texture = new THREE.CanvasTexture(canvas);
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;

  const emissiveTexture = new THREE.CanvasTexture(emissiveCanvas);
  emissiveTexture.magFilter = THREE.LinearFilter;
  emissiveTexture.minFilter = THREE.LinearFilter;

  // Material
  const material = new THREE.MeshStandardNodeMaterial({
    map: texture,
    color: new THREE.Color(colors.surface),
    roughness: 0.6,
    metalness: 0.2,
    emissiveMap: emissiveTexture,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.5,
    side: THREE.DoubleSide
  });

  // Mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.z = 0.02;
  group.add(mesh);

  // Animation
  const contentWidth = canvas.width / 2;
  const pixelsPerSecond = pixelsPerUnitX * 0.4;
  const loopDuration = contentWidth / pixelsPerSecond;

  const offsetProxy = { x: 0 };
  const timeline = gsap.timeline({ repeat: -1 });

  timeline.to(offsetProxy, {
    x: 0.5,
    duration: loopDuration,
    ease: 'none',
    onUpdate: () => {
      material.map.offset.x = offsetProxy.x;
      emissiveTexture.offset.x = offsetProxy.x;
    }
  });

  // Apply fly-through primitive
  if (ctx.primitives?.['fly-through']) {
    ctx.primitives['fly-through'](group, {
      depthUnits: 0,
      speed: 0.4
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    timeline.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
    emissiveTexture.dispose();
  };

  return group;
}
